drop policy if exists inventory_locations_manage on public.inventory_locations;create policy inventory_locations_insert on public.inventory_locations for insert to authenticated with check(public.current_user_role() in ('admin','site_manager','storekeeper'));create policy inventory_locations_update on public.inventory_locations for update to authenticated using(public.current_user_role() in ('admin','site_manager','storekeeper')) with check(public.current_user_role() in ('admin','site_manager','storekeeper'));create policy inventory_locations_delete on public.inventory_locations for delete to authenticated using(public.current_user_role() in ('admin','site_manager','storekeeper'));drop policy if exists item_schedules_manage on public.item_schedules;create policy item_schedules_insert on public.item_schedules for insert to authenticated with check(public.current_user_role() in ('admin','site_manager','storekeeper'));create policy item_schedules_update on public.item_schedules for update to authenticated using(public.current_user_role() in ('admin','site_manager','storekeeper')) with check(public.current_user_role() in ('admin','site_manager','storekeeper'));create policy item_schedules_delete on public.item_schedules for delete to authenticated using(public.current_user_role() in ('admin','site_manager','storekeeper'));
create index if not exists boq_additions_approved_by_idx on public.boq_additions(approved_by);create index if not exists boq_additions_created_by_idx on public.boq_additions(created_by);create index if not exists inventory_locations_created_by_idx on public.inventory_locations(created_by);create index if not exists inventory_tx_destination_location_idx on public.inventory_transactions(destination_location_id);create index if not exists inventory_tx_source_location_idx on public.inventory_transactions(source_location_id);create index if not exists inventory_tx_reversal_of_idx on public.inventory_transactions(reversal_of);create index if not exists inventory_tx_reversed_by_idx on public.inventory_transactions(reversed_by);create index if not exists item_schedules_updated_by_idx on public.item_schedules(updated_by);create index if not exists project_control_updated_by_idx on public.project_control(updated_by);